import * as THREE from './vendor/three.module.js';
import {planeData,FT,junctionReport,vertexJunctionReport,planeEquation} from './geometry.mjs';
export function createViewer(host){
 const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor('#0a2032');renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;host.append(renderer.domElement);
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(40,1,.01,100000);scene.fog=new THREE.Fog(0x0a2032,180,1200);scene.add(new THREE.HemisphereLight(0xd9f4ff,0x172838,2.15));const sun=new THREE.DirectionalLight(0xfff4df,3);sun.position.set(60,110,45);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-250;sun.shadow.camera.right=250;sun.shadow.camera.top=250;sun.shadow.camera.bottom=-250;scene.add(sun);
 let group=new THREE.Group();scene.add(group);let target=new THREE.Vector3(),radius=40,theta=.6,phi=.9,drag=null;
 function draw(force=false,width=0,height=0){if(host.hidden&&!force)return;const w=width||host.clientWidth||900,h=height||host.clientHeight||560;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();camera.position.set(target.x+radius*Math.sin(phi)*Math.sin(theta),target.y+radius*Math.cos(phi),target.z+radius*Math.sin(phi)*Math.cos(theta));camera.lookAt(target);renderer.render(scene,camera)}
 renderer.domElement.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;theta-=(e.clientX-drag.x)*.009;phi=Math.max(.06,Math.min(Math.PI/2-.025,phi+(e.clientY-drag.y)*.009));drag={x:e.clientX,y:e.clientY};draw()});renderer.domElement.addEventListener('pointerup',()=>drag=null);renderer.domElement.addEventListener('pointercancel',()=>drag=null);renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();radius=Math.max(1,Math.min(10000,radius*Math.exp(e.deltaY*.001)));draw()},{passive:false});new ResizeObserver(()=>draw()).observe(host);
 function clear(){group.traverse(x=>{x.geometry?.dispose();if(Array.isArray(x.material))x.material.forEach(m=>m.dispose());else x.material?.dispose()});scene.remove(group);group=new THREE.Group();scene.add(group)}
 function line(points,color,width=1){const g=new THREE.BufferGeometry().setFromPoints(points);const l=new THREE.Line(g,new THREE.LineBasicMaterial({color,linewidth:width}));group.add(l)}
 function marker(point,color,radius=.14){const dot=new THREE.Mesh(new THREE.SphereGeometry(radius,18,12),new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.2,roughness:.5}));dot.position.copy(point);group.add(dot)}
 function mesh(points,data,color,offset=0){const contour=points.map(p=>new THREE.Vector2(p.x,p.y));const indices=THREE.ShapeUtils.triangulateShape(contour,[]).flat();const positions=points.flatMap(p=>[p.x,data.height(p)+offset,-p.y]);const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geometry.setIndex(indices);geometry.computeVertexNormals();const roof=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({color,metalness:.48,roughness:.38,side:THREE.DoubleSide,polygonOffset:true,polygonOffsetFactor:1,polygonOffsetUnits:1}));roof.castShadow=true;roof.receiveShadow=true;group.add(roof)}
 const seamKey=(a,b)=>[a,b].map(p=>`${p.x.toFixed(3)},${p.y.toFixed(3)}`).sort().join('|');
 function fascia(points,data,shared){for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length];if(shared.has(seamKey(a,b)))continue;const topA=data.height(a),topB=data.height(b),depth=.14,geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute([a.x,topA,-a.y,b.x,topB,-b.y,b.x,topB-depth,-b.y,a.x,topA-depth,-a.y],3));geometry.setIndex([0,1,2,0,2,3]);geometry.computeVertexNormals();const side=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({color:0x203f50,metalness:.3,roughness:.55,side:THREE.DoubleSide}));side.castShadow=true;group.add(side)}}
 function update(state,summary,showPanels,reset){clear();const faceData=new Map(),joints=junctionReport(state.faces,state.origin),vertexJoints=vertexJunctionReport(state.faces,state.origin),shared=new Set(joints.map(j=>seamKey(j.a,j.b)));for(const row of summary.rows){const data=planeData(row.face,state.origin);faceData.set(row.face.id,data);mesh(data.points,data,state.settings.color);fascia(data.points,data,shared);const to3=(p,offset=0)=>new THREE.Vector3(p.x,data.height(p)+offset,-p.y);line([...data.points,data.points[0]].map(p=>to3(p,.015)),0xbcefff);if(showPanels)for(const panel of row.panels){line([...panel.polygon,panel.polygon[0]].map(p=>to3(p,.035)),panel.oversize?0xffb960:0xc5e3e9)}
 // Vertical reference lines make the entered low-edge height visible.
 for(const p of data.points)line([new THREE.Vector3(p.x,0,-p.y),to3(p)],0x274a60);
 }
 // Validate each shared seam against both pitched plane equations. Conflicts
 // stay visible instead of being hidden by moving user-authored geometry.
 for(const joint of joints){const left=faceData.get(joint.left.face.id),right=faceData.get(joint.right.face.id),color=joint.status==='aligned'?0x58e3a5:joint.status==='offset'?0xffc44d:0xff5573,toAverage=p=>new THREE.Vector3(p.x,(left.height(p)+right.height(p))/2+.06,-p.y);line([toAverage(joint.a),toAverage(joint.b)],color,3);if(joint.status!=='aligned')for(const p of [joint.a,joint.b])line([new THREE.Vector3(p.x,left.height(p),-p.y),new THREE.Vector3(p.x,right.height(p),-p.y)],0xff5573,3)}
 for(const joint of vertexJoints)if(joint.status!=='aligned'){const heights=joint.faces.map(face=>planeEquation(face,state.origin).height(joint.point)),average=heights.reduce((sum,height)=>sum+height,0)/heights.length,center=new THREE.Vector3(joint.point.x,average+.08,-joint.point.y);marker(center,0xff5573,.18);for(const height of heights)line([new THREE.Vector3(joint.point.x,height,-joint.point.y),center],0xff5573,3)}
 const bounds=new THREE.Box3().setFromObject(group);const size=new THREE.Vector3();if(!bounds.isEmpty()){bounds.getSize(size);if(reset){bounds.getCenter(target);radius=Math.max(size.x,size.y,size.z)*2.2+5}}else{target.set(0,0,0);radius=30}
 const gridSize=Math.max(30,Math.ceil(Math.max(size.x,size.z)*1.6/10)*10),ground=new THREE.Mesh(new THREE.PlaneGeometry(gridSize,gridSize),new THREE.ShadowMaterial({color:0x020b12,opacity:.32}));ground.rotation.x=-Math.PI/2;ground.position.set(target.x,-.025,target.z);ground.receiveShadow=true;group.add(ground);const grid=new THREE.GridHelper(gridSize,Math.min(100,gridSize),0x35617a,0x18384f);grid.position.set(target.x,0,target.z);group.add(grid);draw();
 }
 function getViewState(){return {target:{x:target.x,y:target.y,z:target.z},radius,theta,phi}}
 function setViewState(saved){if(!saved)return;target.set(saved.target?.x||0,saved.target?.y||0,saved.target?.z||0);radius=Math.max(1,Math.min(10000,Number(saved.radius)||radius));theta=Number.isFinite(Number(saved.theta))?Number(saved.theta):theta;phi=Math.max(.06,Math.min(Math.PI/2-.025,Number(saved.phi)||phi));draw()}
 function captureViews(){const current=getViewState(),presets=[['Front perspective',0,.92],['Rear perspective',Math.PI,.92],['Left-side perspective',-Math.PI/2,.92],['Right-side perspective',Math.PI/2,.92],['Isometric / top perspective',Math.PI/4,.55]],images=[];for(const [label,nextTheta,nextPhi]of presets){theta=nextTheta;phi=nextPhi;draw(true,900,560);images.push({label,data:renderer.domElement.toDataURL('image/jpeg',.88)})}setViewState(current);return images}
 return {update,getViewState,setViewState,captureViews};
}
